compatible.keydesc:
{
"en":"App icon display repair",
"ch":"应用内图标显示修复"
}

compatible.notes:
{
"en":"Application icon display fix: Solve the issue of incomplete display of application icons in non-full-screen mode.",
"ch":"应用内图标显示修复：解决非全屏模式下应用内图标显示不全。"
}

compatible.keydesc:
{
"en":"Application window fixed maximization",
"ch":"应用窗口固定最大化"
}

compatible.notes:
{
 "en":"Application window fixed maximization: Solve the problem of some gaming applications unable to display and operate in non-full-screen mode.",
 "ch":"应用窗口固定最大化：解决非全屏模式下部分游戏类应用无法显示和操作。"
}

compatible.keydesc:
{
"en":"Remove screenshot recording restrictions",
"ch":"解除截图录屏限制"
}

compatible.notes:
{
"en":"Remove screenshot and screen recording restrictions: Resolve the issue of certain application interfaces being unable to be captured or recorded.",
"ch":"解除截图录屏限制：解决应用部分界面无法截图和录屏。"
}

{
"en":"Application virtual resolution ratio: Addressing the limitation of certain application functionalities being restricted under the system's default resolution ratio.",
"ch":"应用虚拟分辨率：解决部分应用在系统预设的分辨率下内部某些功能被限制使用。"
}

compatible.keydesc:
{
"en":"Linux apps support for multiple windows",
"ch":"融合应用支持多窗口"
}

compatible.notes:
{
"en":"Open fusion application in multi window mode, only valid for Linux",
"ch":"多窗口模式打开融合应用，仅对Linux有效"
}

compatible.keydesc:
{
"en":"Minimum width of application window",
"ch":"应用窗口最小宽度"
}

compatible.notes:
{
"en":"Minimum width of application window: The minimum adjustable width of the application window in freeform window mode",
"ch":"应用窗口最小宽度: 自由窗口模式下应用窗口可调整的最小宽度"
}

compatible.keydesc:
{
"en":"Minimum height of application window",
"ch":"应用窗口最小高度"
}

compatible.notes:
{
"en":"Minimum height of application window: The minimum adjustable height of the application window in freeform window mode",
"ch":"应用窗口最小高度: 自由窗口模式下应用窗口可调整的最小高度"
}

compatible.keydesc:
{
"en":"Turn off simulated touch",
"ch":"关闭模拟触摸"
}

compatible.notes:
{
"en":"Turn off simulated touch: Solve the problem of remote control applications being unable to operate the scroll wheel.",
"ch":"关闭模拟触摸：解决远控类应用无法操作滚轮的问题。"
}

compatible.keydesc:
{
"en":"Window size limit",
"ch":"限制应用内窗口大小"
}

compatible.notes:
{
"en":"Limit the screen size used for pop-ups within the app to the current size of the app window.",
"ch":"限制应用内弹窗使用的屏幕尺寸为当前应用窗口尺寸。"
}

{
"en":"To display multiple windows of one application by enabling magic window",
"ch":"启用平行视界，可以平行显示同一个应用的多个窗口"
}

compatible.keydesc:
{
"en":"Do not allow running in the background",
"ch":"不允许后台运行"
}

compatible.notes:
{
"en":"Do not allow running in the background: Resolves the issue where certain applications such as Carrot Fantasy 4 cannot be reopened after being closed",
"ch":"不允许后台运行：解决部分应用（如保卫萝卜4）关闭后无法再打开问题"
}

{
"en":"apply resource resolution:  Addressing Layout Display Issues for Certain Applications (e.g., WeChat) at System-Preset Resolutions",
"ch":"应用资源分辨率：解决部分应用（如微信）在系统预设的分辨率下布局显示过大或过小。"
}

{
"en":"Enable vertical mode, disable max, full screen mode, and zoom functions",
"ch":"启用竖屏模式，禁用最大化、全屏模式、缩放功能"
}

compatible.keydesc:
{
"en":"Fix activity size",
"ch":"固定应用启动大小"
}

compatible.notes:
{
"en":"Fix app lunch size",
"ch":"固定应用启动大小"
}
